def knapsack(W, wt, val, k):
    K = [[0 for w in range(W + 1)]
            for i in range(k + 1)]

    for i in range(k + 1):
        for w in range(W + 1):
            if i == 0 or w == 0:
                K[i][w] = 0
            elif wt[i-1] <= w:
                K[i][w] = max(val[i-1] 
+ K[i-1][w-wt[i-1]],  K[i-1][w])
            else:
                K[i][w] = K[i-1][w]

    return K[k][W]

