    if n == 0:
        return 0
    elif n < 0:
        n = n * -1
    digits = [int(d) for d in str(n)]
    for i in range(len(digits)):
        lower = int(''.join([str(d) for d in digits[:i]+[str(d-1)]*len(digits[i:])]))
        higher = int(''.join([str(d) for d in digits[:i]+[str(d+1)]*len(digits[i:])]))
