def merge_sorted_list(*lists):
    merged = []
    for lst in lists:
        heapq.heapify(lst)
    while lists:
        smallest = [heapq.heappop(lst) for lst in lists]
        merged.append(min(smallest))
        for lst in lists:
            if smallest[0] == lst[0]:
                lst.pop(0)
                if lst:
                    heapq.heappush(lst, lst[0])
                else:
                    lists.remove(lst)
    return merged

