def reverse_vowels(str):
    vowels = 'aeiouAEIOU'
    str = list(str)
    i, j = 0, len(str) - 1
    while i < j:
        if str[i] in vowels:
            if str[j] in vowels:
                str[i], str[j] = str[j], str[i]
                i += 1
                j -= 1
            else:
