def parabola_vertex(a, b, c):
    discriminant = b**2 - 4*a*c
    if discriminant > 0:
        x1 = (-b + math.sqrt(discriminant)) / (2*a)
        y1 = (a*x1**2 + b*x1 + c) / a
        return (x1, y1)
    elif discriminant == 0:
        x1 = -b / (2*a)
        y1 = (a*x1**2 + b*x1 + c) / a
        return (x1, y1)
    else:
        x1 = (-b - math.sqrt(discriminant)) / (2*a)
        y1 = (a*x1**2 + b*x1 + c) / a
        return (x1, y1)

