    for num in arr:
        if str(num) == str(num)[::-1]:
            palindromes.append(num)
    if len(palindromes) < k:
        return None
    else:
        return max(palindromes[:k])

def largest_palindrome(arr, n):
    largest = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)+1):
            sub_arr = arr[i:j]
            if sub_arr == sub_arr[::-1]:
                largest = max(largest, int(''.join(map(str, sub_arr))))
    return largest

